/**
 * Document DXP Component -- Server-Side Renderer
 *
 * Plain presentational render -- every value is supplied directly as an
 * input; this component does not resolve a Squiz asset itself (see
 * document.spec.md assumption 1).
 */

const FILE_ICONS = {
  pdf: "fa-file-pdf",
  doc: "fa-file-word",
  docx: "fa-file-word",
  ppt: "fa-file-powerpoint",
  pptx: "fa-file-powerpoint",
  xls: "fa-file-excel",
  xlsx: "fa-file-excel",
};
const DEFAULT_FILE_ICON = "fa-file";

function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function fileIconClass(fileType) {
  const key = String(fileType ?? "").toLowerCase();
  return FILE_ICONS[key] || DEFAULT_FILE_ICON;
}

export default {
  async main(input) {
    const {
      title = "",
      href = "#",
      fileType = "",
      fileSize = "",
      description = "",
      ariaLabel = "",
      metadata = "",
      target = "",
      rel = "",
      download = false,
    } = input || {};

    const metaLine = metadata || [fileType.toUpperCase(), fileSize].filter(Boolean).join(" | ");

    const linkAttrs = [
      ariaLabel ? ` aria-label="${esc(ariaLabel)}"` : "",
      target ? ` target="${esc(target)}"` : "",
      rel ? ` rel="${esc(rel)}"` : "",
      download ? ` download` : "",
    ].join("");

    const descriptionHtml = description
      ? `<p class="document__description" data-sq-field="description">${esc(description)}</p>`
      : "";

    return /*html*/`
<div class="document">
  <div class="document__header">
    <div class="document__icon-wrapper">
      <div class="document__icon">
        <i class="fa-thin ${fileIconClass(fileType)}" aria-hidden="true"></i>
      </div>
    </div>
    <div class="document__meta">
      <a href="${esc(href)}" class="document__title" data-sq-field="title"${linkAttrs}>${esc(title)}</a>
      <span class="document__info" data-sq-field="metadata">${esc(metaLine)}</span>
    </div>
  </div>
  ${descriptionHtml}
</div>
`;
  },
};
