import { html } from 'lit';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import comp from './main.js';

/**
 * "Show code" can't dynamically capture our output: the shared
 * squizStoryRenderer wraps it in lit's until() because main() is async
 * (per the DXP edge contract), but Storybook's web-components source
 * decorator reads the rendered container's innerHTML synchronously, before
 * that promise resolves -- so dynamic capture always sees an empty result.
 * Precomputing the real HTML here and handing it to Storybook explicitly
 * is the only reliable way to show it.
 *
 * This component takes plain literal props (no Squiz asset resolution --
 * see document.spec.md assumption 1), so unlike card/image-gallery/
 * topic-listing, main() never needs an `info` argument at all here.
 */
const squiz = squizStoryRenderer(comp.main);

export default {
  title: 'dxp/Document',
  parameters: {
    layout: 'padded',
  },
};

const defaultArgs = {
  title: 'This is the document title',
  href: '#',
  fileType: 'docx',
  fileSize: '182 KB',
  description: 'Optional description of the document.',
};
const defaultHtml = await squiz.markup(defaultArgs);

export const Default = {
  render: (args) => squiz(args),
  args: defaultArgs,
  argTypes: {
    title: { control: 'text' },
    href: { control: 'text' },
    fileType: { control: 'select', options: ['pdf', 'doc', 'docx', 'ppt', 'pptx', 'xls', 'xlsx'] },
    fileSize: { control: 'text' },
    description: { control: 'text', description: 'Leave blank to omit the description entirely.' },
    ariaLabel: { control: 'text' },
    metadata: { control: 'text', description: 'Overrides the auto-generated "TYPE | SIZE" line when set.' },
    target: { control: 'text' },
    rel: { control: 'text' },
    download: { control: 'boolean' },
  },
  parameters: {
    docs: {
      source: { code: defaultHtml, language: 'html', type: 'code' },
    },
  },
};

const withoutDescriptionArgs = {
  title: 'This is the document title',
  href: '#',
  fileType: 'xlsx',
  fileSize: '2.4 MB',
};
const withoutDescriptionHtml = await squiz.markup(withoutDescriptionArgs);

export const WithoutDescription = {
  render: () => squiz(withoutDescriptionArgs),
  parameters: {
    docs: {
      description: { story: '`description` is omitted -- the description paragraph is not rendered at all.' },
      source: { code: withoutDescriptionHtml, language: 'html', type: 'code' },
    },
  },
};

const pdfArgs = {
  title: 'This is the document title',
  href: '#',
  fileType: 'pdf',
  fileSize: '182 KB',
  description: 'Optional description of the document.',
};
const pdfHtml = await squiz.markup(pdfArgs);

export const PDF = {
  render: () => squiz(pdfArgs),
  parameters: {
    docs: { source: { code: pdfHtml, language: 'html', type: 'code' } },
  },
};

const xlsxArgs = {
  title: 'This is the document title',
  href: '#',
  fileType: 'xlsx',
  fileSize: '182 KB',
  description: 'Optional description of the document.',
};
const xlsxHtml = await squiz.markup(xlsxArgs);

export const XLSX = {
  render: () => squiz(xlsxArgs),
  parameters: {
    docs: { source: { code: xlsxHtml, language: 'html', type: 'code' } },
  },
};

const pptxArgs = {
  title: 'This is the document title',
  href: '#',
  fileType: 'pptx',
  fileSize: '182 KB',
  description: 'Optional description of the document.',
};
const pptxHtml = await squiz.markup(pptxArgs);

export const PPTX = {
  render: () => squiz(pptxArgs),
  parameters: {
    docs: { source: { code: pptxHtml, language: 'html', type: 'code' } },
  },
};

const allFileTypesItems = [
  { fileType: 'docx', fileSize: '182 KB' },
  { fileType: 'pdf', fileSize: '946 KB' },
  { fileType: 'xlsx', fileSize: '1.1 MB' },
  { fileType: 'pptx', fileSize: '4.8 MB' },
];
const allFileTypesCards = await Promise.all(allFileTypesItems.map((item) => comp.main({
  title: 'This is the document title',
  href: '#',
  description: 'Optional description of the document.',
  ...item,
})));
const allFileTypesHtml = allFileTypesCards.join('\n');
const allFileTypesWrapped = `<div style="display:grid;grid-template-columns:repeat(3, 1fr);gap:var(--sp-xl) var(--sp-2xl);align-items:start">${allFileTypesHtml}</div>`;

export const AllFileTypes = {
  // Multiple document cards, 3 per row -- main() only ever renders one card, so this bypasses the
  // shared squiz() helper (built for a single main() call) and renders the
  // already-precomputed, joined result directly via lit's unsafeHTML.
  render: () => html`${unsafeHTML(allFileTypesWrapped)}`,
  parameters: {
    docs: {
      description: { story: 'Every supported file type, laid out 3 cards per row.' },
      source: { code: allFileTypesHtml, language: 'html', type: 'code' },
    },
  },
};
